# Load all grids from session log (both test input and any demos)
import os,re,json,dotenv

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

def parse_grids():
    grids = {}
    # Find "Test input" or "Demo pair" sections
    for m in re.finditer(r'(?:(Demo pair \d+ (?:input|output)|Test input)) \((\d+)x(\d+)\):\n', t):
        kind, h, w = m.groups()
        k = kind.split(' ')[-1]  # "Test input" or "Demo pair X input/output"
        rows_text = t[m.end():m.end()+h*w+20].replace('\n\n', '\n')
        # Parse rows - they're space-separated integers
        rows = []
        for line in t[m.end():].split('\n')[:h]:
            row = [int(x) for x in line.strip().split() if x.isdigit()]
            if len(row) == w:
                rows.append(row)
        if rows and all(len(r)==w for r in rows) and all(all(c.isdigit() for c in r) for r in rows):
            grids[k] = rows
        else:
            print(f"Failed to parse {kind}: got {len(rows)} rows")
    return grids

G = parse_grids()
print("Loaded grids:")
for k, rows in sorted(G.items()):
    print(f"  {k}: {len(rows)}x{len(rows[0])}")

